import os, fnmatch
roots = ['/']
skip = {'/proc','/sys','/dev','/run','/usr/lib','/usr/share/doc'}
needles = {
    'orig_wal_header': bytes.fromhex('753d44c0426fa05a'),
    'wal_magic_plain': bytes.fromhex('377f0682'),
    'elderberry': b'elderberry',
    'honeydew': b'honeydew',
}
hits = {k: [] for k in needles}
for root in roots:
    for dirpath, dirnames, filenames in os.walk(root, topdown=True):
        dirnames[:] = [d for d in dirnames if os.path.join(dirpath,d) not in skip and d not in ('proc','sys','dev')]
        for fn in filenames:
            p = os.path.join(dirpath, fn)
            try:
                if not os.path.isfile(p) or os.path.islink(p): continue
                st = os.stat(p)
                if st.st_size > 200*1024*1024: continue
                data = open(p,'rb').read()
            except Exception:
                continue
            for k, n in needles.items():
                if n in data:
                    hits[k].append((p, st.st_size))
for k,v in hits.items():
    print('===', k, len(v))
    for p,s in v[:40]: print('   ', p, s)
EOF
